export function isBalanced(s) {
  const close = { ")": "(", "]": "[", "}": "{" };
  const stack = [];
  for (const c of String(s)) {
    if ("([{".includes(c)) stack.push(c);
    else if (close[c]) { if (stack.pop() !== close[c]) return false; }
  }
  return stack.length === 0;
}

